        ops = diff_text("Pay 5% now.", "Pay 7% later.")
        self.assertEqual(ops, [("=", "Pay"), ("-", "5"), ("+", "7"), ("=", "%"), ("-", "now"), ("+", "later"), ("=", ".")])

    def test_inputs_not_modified(self):
        a, b = ["a", "b"], ["b", "c"]
        diff(a, b)
        self.assertEqual((a, b), (["a", "b"], ["b", "c"]))


